    'Sign in to explore products, discover artisans, and purchase traditional crafts.': 'ఉత్పత్తులను అన్వేషించడానికి, కళాకారులను కనుగొనడానికి మరియు సాంప్రదాయ చేతిపనులను కొనుగోలు చేయడానికి సైన్ ఇన్ చేయండి.',
    'Sign in to access Artisan Studio': 'కళాకారుల స్టూడియో కోసం సైన్ ఇన్ చేయండి',
    'Sign in to manage your products, use AI tools, discover opportunities, and collaborate with artisans.': 'మీ ఉత్పత్తులను నిర్వహించడానికి, AI సాధనాలను ఉపయోగించడానికి మరియు కళాకారులతో సహకరించడానికి సైన్ ఇన్ చేయండి.',
