    'Your session has expired. Please sign in again.': 'మీ సెషన్ గడువు ముగిసింది. దయచేసి మళ్లీ సైన్ ఇన్ చేయండి.',
    'Sign in to continue to DesiCraft Marketplace.': 'దేశీ క్రాఫ్ట్ మార్కెట్‌ప్లేస్‌కి కొనసాగడానికి సైన్ ఇన్ చేయండి.',
    'Sign in to enter Artisan Studio.': 'కళాకారుల స్టూడియోలోకి ప్రవేశించడానికి సైన్ ఇన్ చేయండి.',
    'Enter Buyer Marketplace': 'కొనుగోలుదారుల మార్కెట్‌లోకి ప్రవేశించండి',
    'Enter Artisan Studio': 'కళాకారుల స్టూడియోలోకి ప్రవేశించండి',
