    languageSelect: 'ಭಾಷೆ ಆಯ್ಕೆಮಾಡಿ',
      'Sign in to access Buyer Marketplace': 'ಖರೀದಿದಾರರ ಮಾರುಕಟ್ಟೆ ಪ್ರವೇಶಿಸಲು ಸೈನ್ ಇನ್ ಮಾಡಿ',
    'Sign in to explore products, discover artisans, and purchase traditional crafts.': 'ಉತ್ಪನ್ನಗಳನ್ನು ಅನ್ವೇಷಿಸಲು, ಕುಶಲಕರ್ಮಿಗಳನ್ನು ಹುಡುಕಲು ಮತ್ತು ಸಾಂಪ್ರದಾಯಿಕ ಕರಕುಶಲ ವಸ್ತುಗಳನ್ನು ಖರೀದಿಸಲು ಸೈನ್ ಇನ್ ಮಾಡಿ.',
    'Sign in to access Artisan Studio': 'ಕುಶಲಕರ್ಮಿ ಸ್ಟುಡಿಯೋ ಪ್ರವೇಶಿಸಲು ಸೈನ್ ಇನ್ ಮಾಡಿ',
    'Sign in to manage your products, use AI tools, discover opportunities, and collaborate with artisans.': 'ನಿಮ್ಮ ಉತ್ಪನ್ನಗಳನ್ನು ನಿರ್ವಹಿಸಲು, AI ಪರಿಕರಗಳನ್ನು ಬಳಸಲು ಮತ್ತು ಕುಶಲಕರ್ಮಿಗಳೊಂದಿಗೆ ಸಹಕರಿಸಲು ಸೈನ್ ಇನ್ ಮಾಡಿ.',
    'Switch to Artisan Studio': 'ಕುಶಲಕರ್ಮಿ ಸ್ಟುಡಿಯೋಗೆ ಬದಲಿಸಿ',
    'Switch to Buyer Marketplace': 'ಖರೀದಿದಾರರ ಮಾರುಕಟ್ಟೆಗೆ ಬದಲಿಸಿ',
    'Checking your session...': 'ನಿಮ್ಮ ಸೆಶನ್ ಪರಿಶೀಲಿಸಲಾಗುತ್ತಿದೆ...',
    'Invalid email or password.': 'ಅಮಾನ್ಯ ಇಮೇಲ್ ಅಥವಾ ಪಾಸ್‌ವರ್ಡ್.',
    'Your session has expired. Please sign in again.': 'ನಿಮ್ಮ ಸೆಶನ್ ಮುಕ್ತಾಯಗೊಂಡಿದೆ. ದಯವಿಟ್ಟು ಮತ್ತೆ ಸೈನ್ ಇನ್ ಮಾಡಿ.',
    'Sign in to continue to DesiCraft Marketplace.': 'ದೇಸಿ ಕ್ರಾಫ್ಟ್ ಮಾರುಕಟ್ಟೆಗೆ ಮುಂದುವರಿಯಲು ಸೈನ್ ಇನ್ ಮಾಡಿ.',
    'Sign in to enter Artisan Studio.': 'ಕುಶಲಕರ್ಮಿ ಸ್ಟುಡಿಯೋ ಪ್ರವೇಶಿಸಲು ಸೈನ್ ಇನ್ ಮಾಡಿ.',
    'Enter Buyer Marketplace': 'ಖರೀದಿದಾರರ ಮಾರುಕಟ್ಟೆಗೆ ಪ್ರವೇಶಿಸಿ',
    'Enter Artisan Studio': 'ಕುಶಲಕರ್ಮಿ ಸ್ಟುಡಿಯೋಗೆ ಪ್ರವೇಶಿಸಿ',
    'Mode-Entry Security Gate': 'ಮೋಡ್-ಪ್ರವೇಶ ಭದ್ರತಾ ದ್ವಾರ',
    'Back to DesiCraft Home': 'ದೇಸಿ ಕ್ರಾಫ್ಟ್ ಮುಖಪುಟಕ್ಕೆ ಹಿಂತಿರುಗಿ',
    'Preserving 5,000 Years of Indian Craft Heritage': '5,000 ವರ್ಷಗಳ ಭಾರತೀಯ ಕರಕುಶಲ ಪರಂಪರೆಯ ಸಂರಕ್ಷಣೆ',
    'Choose your mode to begin:': 'ಪ್ರಾರಂಭಿಸಲು ನಿಮ್ಮ ಮೋಡ್ ಆಯ್ಕೆಮಾಡಿ:',
    'Access Buyer Marketplace and discover India\'s traditional crafts.': 'ಖರೀದಿದಾರರ ಮಾರುಕಟ್ಟೆಯನ್ನು ಪ್ರವೇಶಿಸಿ ಮತ್ತು ಭಾರತದ ಸಾಂಪ್ರದಾಯಿಕ ಕರಕುಶಲ ವಸ್ತುಗಳನ್ನು ಅನ್ವೇಷಿಸಿ.',
    'Access Artisan Studio and manage your artisan workspace.': 'ಕುಶಲಕರ್ಮಿ ಸ್ಟುಡಿಯೋ ಪ್ರವೇಶಿಸಿ ಮತ್ತು ನಿಮ್ಮ ಡಿಜಿಟಲ್ ಮಗ್ಗ ಕಾರ್ಯಕ್ಷೇತ್ರವನ್ನು ನಿರ್ವಹಿಸಿ.',
    'Editing': 'ಎಡಿಟ್ ಮಾಡಲಾಗುತ್ತಿದೆ',
    'Temporarily unavailable': 'ತಾತ್ಕಾಲಿಕವಾಗಿ ಲಭ್ಯವಿಲ್ಲ',
    'Editing — Hidden from customers': 'ಎಡಿಟ್ ಆಗುತ್ತಿದೆ — ಗ್ರಾಹಕರಿಂದ ಮರೆಮಾಡಲಾಗಿದೆ',
    'Product updated successfully.': 'ಉತ್ಪನ್ನವನ್ನು ಯಶಸ್ವಿಯಾಗಿ ನವೀಕರಿಸಲಾಗಿದೆ.',
    'Unable to update product. Your product is still hidden from customers. Please try again.': 'ಉತ್ಪನ್ನ ನವೀಕರಿಸಲು ಸಾಧ್ಯವಾಗಲಿಲ್ಲ. ನಿಮ್ಮ ಉತ್ಪನ್ನವು ಗ್ರಾಹಕರಿಂದ ಮರೆಯಾಗಿದೆ. ದಯವಿಟ್ಟು ಮತ್ತೆ ಪ್ರಯತ್ನಿಸಿ.',
    'Product temporarily unavailable while the seller updates it.': 'ಮಾರಾಟಗಾರರು ನವೀಕರಿಸುತ್ತಿರುವಾಗ ಉತ್ಪನ್ನ ತಾತ್ಕಾಲಿಕವಾಗಿ ಲಭ್ಯವಿಲ್ಲ.',
    'Product is currently being edited by another session.': 'ಉತ್ಪನ್ನವನ್ನು ಪ್ರಸ್ತುತ ಇನ್ನೊಂದು ಸೆಶನ್ ಸಂಪಾದಿಸುತ್ತಿದೆ.',
    'Sorry, this product is temporarily unavailable.': 'ಕ್ಷಮಿಸಿ, ಈ ಉತ್ಪನ್ನವು ತಾತ್ಕಾಲಿಕವಾಗಿ ಲಭ್ಯವಿಲ್ಲ.',
    'Saving changes...': 'ಬದಲಾವಣೆಗಳನ್ನು ಉಳಿಸಲಾಗುತ್ತಿದೆ...',
    'Edit Product': 'ಉತ್ಪನ್ನ ಸಂಪಾದಿಸಿ',
    'Cancel Edit': 'ಸಂಪಾದನೆ ರದ್ದುಮಾಡಿ',
    'Save Changes': 'ಬದಲಾವಣೆಗಳನ್ನು ಉಳಿಸಿ',
    'Retry': 'ಮತ್ತೆ ಪ್ರಯತ್ನಿಸಿ',
    'Continue Editing': 'ಸಂಪಾದನೆ ಮುಂದುವರಿಸಿ',
    'Product Price (₹ INR)': 'ಉತ್ಪನ್ನದ ಬೆಲೆ (₹ INR)',
    'Product Description': 'ಉತ್ಪನ್ನ ವಿವರಣೆ',
    'Enter detailed craft description...': 'ವಿವರವಾದ ಕರಕುಶಲ ವಿವರಣೆಯನ್ನು ನಮೂದಿಸಿ...',
    'Editing mode active — Product is temporarily hidden from customers.': 'ಸಂಪಾದನೆ ಮೋಡ್ ಸಕ್ರಿಯ — ಉತ್ಪನ್ನವನ್ನು ತಾತ್ಕಾಲಿಕವಾಗಿ ಗ್ರಾಹಕರಿಂದ ಮರೆಮಾಡಲಾಗಿದೆ.',
    'Editing cancelled. Product visibility restored.': 'ಸಂಪಾದನೆ ರದ್ದುಗೊಳಿಸಲಾಗಿದೆ. ಉತ್ಪನ್ನದ ಗೋಚರತೆಯನ್ನು ಮರುಸ್ಥಾಪಿಸಲಾಗಿದೆ.',
    'Purchasing paused while the seller updates this handcrafted masterpiece.': 'ಮಾರಾಟಗಾರರು ಈ ಕಲಾಕೃತಿಯನ್ನು ನವೀಕರಿಸುತ್ತಿರುವಾಗ ಖರೀದಿ ಸ್ಥಗಿತಗೊಂಡಿದೆ.',
    'Invalid price: Price must be greater than zero.': 'ಅಮಾನ್ಯ ಬೆಲೆ: ಬೆಲೆಯು ಶೂನ್ಯಕ್ಕಿಂತ ಹೆಚ್ಚಾಗಿರಬೇಕು.',
