    'Sign in to access Artisan Studio': 'കരകൗശല സ്റ്റുഡിയോയിലേക്ക് പ്രവേശിക്കാൻ സൈൻ ഇൻ ചെയ്യുക',
    'Sign in to manage your products, use AI tools, discover opportunities, and collaborate with artisans.': 'നിങ്ങളുടെ ഉൽപ്പന്നങ്ങൾ കൈകാര്യം ചെയ്യാനും AI ടൂളുകൾ ഉപയോഗിക്കാനും കരകൗശല വിദഗ്ധരുമായി സഹകരിക്കാനും സൈൻ ഇൻ ചെയ്യുക.',
