    'Your session has expired. Please sign in again.': 'നിങ്ങളുടെ സെഷൻ കാലഹരണപ്പെട്ടു. ദയവായി വീണ്ടും സൈൻ ഇൻ ചെയ്യുക.',
    'Sign in to continue to DesiCraft Marketplace.': 'ദേശി ക്രാഫ്റ്റ് മാർക്കറ്റിലേക്ക് തുടരാൻ സൈൻ ഇൻ ചെയ്യുക.',
    'Sign in to enter Artisan Studio.': 'കരകൗശല സ്റ്റുഡിയോയിൽ പ്രവേശിക്കാൻ സൈൻ ഇൻ ചെയ്യുക.',
    'Enter Buyer Marketplace': 'വാങ്ങുന്നയാളുടെ മാർക്കറ്റിലേക്ക് പ്രവേശിക്കുക',
    'Enter Artisan Studio': 'കരകൗശല സ്റ്റുഡിയോയിലേക്ക് പ്രവേശിക്കുക',
