    'Preserving 5,000 Years of Indian Craft Heritage': '5,000 വർഷത്തെ ഇന്ത്യൻ കരകൗശല പാരമ്പര്യം സംരക്ഷിക്കുന്നു',
    'Choose your mode to begin:': 'ആരംഭിക്കാൻ നിങ്ങളുടെ മോഡ് തിരഞ്ഞെടുക്കുക:',
    'Access Buyer Marketplace and discover India\'s traditional crafts.': 'വാങ്ങുന്നയാളുടെ മാർക്കറ്റിലേക്ക് പ്രവേശിച്ച് ഇന്ത്യയുടെ പരമ്പരാഗത കരകൗശല വസ്തുക്കൾ കണ്ടെത്തുക.',
    'Access Artisan Studio and manage your artisan workspace.': 'കരകൗശല സ്റ്റുഡിയോയിലേക്ക് പ്രവേശിച്ച് നിങ്ങളുടെ ഡിജിറ്റൽ തറി വർക്ക്‌സ്‌പേസ് കൈകാര്യം ചെയ്യുക.',
