    'Product updated successfully.': 'ഉൽപ്പന്നം വിജയകരമായി പുതുക്കി.',
    'Unable to update product. Your product is still hidden from customers. Please try again.': 'ഉൽപ്പന്നം അപ്‌ഡേറ്റ് ചെയ്യാനായില്ല. ഉൽപ്പന്നം ഇപ്പോഴും ഉപഭോക്താക്കളിൽ നിന്ന് മറച്ചിരിക്കുന്നു. വീണ്ടും ശ്രമിക്കുക.',
    'Product temporarily unavailable while the seller updates it.': 'വിൽപ്പനക്കാരൻ അപ്‌ഡേറ്റ് ചെയ്യുന്നതിനാൽ ഉൽപ്പന്നം താൽക്കാലികമായി ലഭ്യമല്ല.',
