      'భారతదేశం అంతటా 5వ తరం మాస్టర్ నేతకారులు, ధోక్రా శిల్పులు మరియు జానపద చిత్రకారులతో నేరుగా కనెక్ట్ అవ్వండి. ప్రతి కళాఖండం అధికారిక జీఐ ట్యాగ్ మరియు డిజిటల్ క్రాఫ్ట్ పాస్‌పోర్ట్‌తో వస్తుంది.',
