    'One account. Two switchable modes.': 'ஒரு கணக்கு. இரண்டு மாறக்கூடிய முறைகள்.',
    'One Account. Two Modes.': 'ஒரு கணக்கு. இரண்டு முறைகள்.',
    'Switch between Customer & Artisan modes anytime in 1 click.': 'வாங்குபவர் மற்றும் கைவினைஞர் முறைகளுக்கு இடையே எப்போது வேண்டுமானாலும் 1 கிளிக்கில் மாறலாம்.',
    'AUTHENTIC INDIAN LIVING HERITAGE ECOSYSTEM': 'உண்மையான இந்திய பாரம்பரிய சூழல் அமைப்பு',
    'Preserving Bharat’s Handcrafted Soul & Living Traditions.': 'பாரதத்தின் கைவினை ஆன்மாவையும் வாழும் மரபுகளையும் பாதுகாத்தல்.',
    'Directly connect with 5th-generation master weavers, lost-wax metallurgists, and folk painters across India. Every masterpiece comes with an official GI Tag and a cryptographic Digital Craft Passport.':
      'இந்தியா முழுவதும் உள்ள 5-ஆம் தலைமுறை தலைசிறந்த நெசவாளர்கள், உலோக கைவினைஞர்கள் மற்றும் நாட்டுப்புற ஓவியர்களுடன் நேரடியாக இணையுங்கள். ஒவ்வொரு படைப்பும் அதிகாரப்பூர்வ புவிசார் குறியீடு மற்றும் டிஜிட்டல் பாஸ்போர்ட்டுடன் வருகிறது.',
