    "Telangana Leather Puppetry": "तेलंगाना चमड़े की कठपुतली",
    "GI Tagged": "जीआई टैग प्रमाणित",
    "The Pride of": "का गौरव",
    "The Pride of Telangana": "तेलंगाना का गौरव",
    "Famous for its intricate tie-and-dye technique, Pochampally Ikat is known for its geometric patterns and vibrant colours. Each piece is a result of precise planning, traditional skill and generations of expertise.": "अपनी जटिल टाई-एंड-डाई तकनीक के लिए प्रसिद्ध, पोचमपल्ली इकत अपने ज्यामितीय पैटर्न और जीवंत रंगों के लिए जाना जाता है। प्रत्येक कृति सटीक योजना, पारंपरिक कौशल और पीढ़ियों की विशेषज्ञता का परिणाम है।",
