    "spots remaining": "स्थान शेष हैं",
    "Mathematical double ikat tie-and-dye handwoven on manual tension pit-looms in Bhoodan Pochampally village. Both warp and weft yarns are pre-calculated, bundled, and dipped in living botanical indigofera and alizarin madder vats to create razor-sharp geometric chevron and diamond motifs. Certified GI craft of Telangana.": "भूदान पोचमपल्ली गांव में पारंपरिक गड्ढा-करघे (पिट लूम) पर हाथ से बुनी गई गणितीय सटीकता वाली डबल इकत टाई-एंड-डाई साड़ी। ताना और बाना दोनों धागों की पहले से गणना की जाती है, उन्हें बांधा जाता है और प्राकृतिक इंडिगोफेरा नील और मजीठ के कुंड में डुबोकर तीखे ज्यामितीय डायमंड पैटर्न बनाए जाते हैं। तेलंगाना का प्रमाणित जीआई शिल्प।",
    "Chitiki Double Ikat Mathematical Tie-and-Dye Weaving on Manual Pit Looms": "मैन्युअल पिट लूम पर चिटिकी डबल इकत गणितीय टाई-एंड-डाई बुनाई",
