    "The weight of the electroplated silver Zari on pure mulberry Katan silk is magnificent. Examining the reverse side confirms authentic Kadwa tapestry weaving with zero loose floating threads. The Digital Craft Passport and QR seal match the official UP GI register perfectly.": "शुद्ध शहतूत कतान सिल्क पर इलेक्ट्रोप्लेटेड चांदी की जरी का वजन और चमक भव्य है। उल्टी तरफ देखने पर बिना किसी ढीले तैरते धागे के प्रामाणिक काढ़वा बुनाई की पुष्टि होती है। डिजिटल क्राफ्ट पासपोर्ट और क्यूआर सील आधिकारिक यूपी जीआई रजिस्टर से पूरी तरह मेल खाते हैं।",
