    "5th-generation master pit-loom weaver from Madanpura, Varanasi. Recipient of National Master Craftsperson Award for revival of antique Kadwa floral brocades.": "मदनपुरा, वाराणसी के 5वीं पीढ़ी के मास्टर पिट-लूम बुनकर। प्राचीन कड़वा फ्लोरल ब्रोकेड के पुनरुद्धार के लिए राष्ट्रीय मास्टर शिल्पकार पुरस्कार से सम्मानित।",
    "Master Ikat tie-and-dye mathematician and master weaver from Bhoodan Pochampally. Renowned for complex double ikat chevrons and training over 80 rural women weavers.": "भूदान पोचमपल्ली की मास्टर इकत टाई-एंड-डाई गणितज्ञ और मास्टर बुनकर। जटिल डबल इकत शेवरॉन और 80 से अधिक ग्रामीण महिला बुनकरों को प्रशिक्षित करने के लिए प्रसिद्ध।",
    "State Awardee artist preserving the traditional Kohbar and Kachni line styles. Her paintings bring ancient ecological folklore to contemporary handmade bamboo-cotton surfaces.": "पारंपरिक कोहबर और कचनी रेखा शैलियों का संरक्षण करने वाली राज्य पुरस्कार विजेता कलाकार। उनके चित्र बांस-कपास की सतहों पर प्राचीन पारिस्थितिक लोककथाओं को जीवंत करते हैं।",
    "Renowned 9th-generation natural dye master and Ajrakh block printer. Globally celebrated for reviving zero-chemical indigo and pomegranate natural mordants.": "प्रसिद्ध 9वीं पीढ़ी के प्राकृतिक रंग मास्टर और अजरख ब्लॉक प्रिंटर। रासायनिक मुक्त नील और अनार के प्राकृतिक बंधकों के पुनरुद्धार के लिए विश्व स्तर पर प्रशंसित।",
    "Direct disciple of master Kripal Singh Shekhawat. Dedicated to preserving single-fire cobalt oxide ceramics and training next-generation studio potters.": "उस्ताद कृपाल सिंह शेखावत के सीधे शिष्य। सिंगल-फायर कोबाल्ट ऑक्साइड सिरेमिक के संरक्षण और अगली पीढ़ी के कुम्हारों को प्रशिक्षित करने के लिए समर्पित।",
    "Tribal Master Metallurgist carrying forward 4,500-year-old Cire Perdue lost-wax casting. Recognized for majestic tribal processional elephants and folk deities.": "4,500 साल पुरानी सिरे परड्यू मोम-ढलाई कला को आगे बढ़ाने वाले जनजातीय मास्टर धातुशिल्पी। भव्य जनजातीय हाथियों और लोक देवी-देवताओं की मूर्तियों के लिए प्रसिद्ध।",
    "Master of the Kani loom and coded Talim scripts. Preserving authentic 100% Changthangi hand-spun pashmina without synthetic blending.": "कानी करघे और कोडित तालीम लिपि के उस्ताद। बिना किसी कृत्रिम मिश्रण के 100% असली चांगथांगी हाथ से कते पश्मीना का संरक्षण।",
