    "The Pride of Telangana": "తెలంగాణ గర్వకారణం",
    "Famous for its intricate tie-and-dye technique, Pochampally Ikat is known for its geometric patterns and vibrant colours. Each piece is a result of precise planning, traditional skill and generations of expertise.": "క్లిష్టమైన టై-అండ్-డై సాంకేతికతకు ప్రసిద్ధి చెందిన పోచంపల్లి ఇక్కత్, రేఖాగణిత నమూనాలు మరియు ఆకర్షణీయమైన రంగులకు పెట్టింది పేరు. ప్రతి కళాఖండం ఖచ్చితమైన గణన, సాంప్రదాయ నైపుణ్యం మరియు తరతరాల అనుభవానికి నిదర్శనం.",
