    "spots remaining": "స్థానాలు మిగిలి ఉన్నాయి",
    "Mathematical double ikat tie-and-dye handwoven on manual tension pit-looms in Bhoodan Pochampally village. Both warp and weft yarns are pre-calculated, bundled, and dipped in living botanical indigofera and alizarin madder vats to create razor-sharp geometric chevron and diamond motifs. Certified GI craft of Telangana.": "భూదాన్ పోచంపల్లి గ్రామంలో సంప్రదాయ గుంత మగ్గాలపై నేసిన గణిత శాస్త్ర ఖచ్చితత్వంతో కూడిన డబుల్ ఇక్కత్ టై-అండ్-డై కళాఖండం. వార్ప్ మరియు వెఫ్ట్ పట్టు దారాలను ముందే లెక్కించి, కట్టలుగా కట్టి, సజీవమైన సహజ నీలిమందు మరియు మంజిష్ట రంగుల తొట్లలో ముంచి అత్యంత నిశితమైన రేఖాగణిత వజ్రపు నమూనాలను సృష్టిస్తారు. తెలంగాణ యొక్క అధికారిక జీఐ సర్టిఫైడ్ చేనేత కళ.",
    "Chitiki Double Ikat Mathematical Tie-and-Dye Weaving on Manual Pit Looms": "మ్యానువల్ గుంత మగ్గాలపై చిటికి డబుల్ ఇక్కత్ గణితాత్మక టై-అండ్-డై నేత",
