    "Registered master artisans can claim free retail stalls at major international airports, railway terminals, and embassies globally.": "నమోదిత మాస్టర్ కళాకారులు అంతర్జాతీయ విమానాశ్రయాలు, రైల్వే టెర్మినల్స్ మరియు రాయబార కార్యాలయాలలో ఉచిత రిటైల్ స్టాల్స్ పొందవచ్చు.",
    "Check District Product Catalog": "జిల్లా ఉత్పత్తుల జాబితాను తనిఖీ చేయండి",
