    "Universal photo identity card granting free health insurance under Ayushman Bharat and direct stall allotment at Dilli Haat and Surajkund Mela.": "ఆయుష్మాన్ భారత్ కింద ఉచిత ఆరోగ్య బీమా మరియు ఢిల్లీ హాట్, సూరజ్‌కుండ్ మేళాలో నేరుగా స్టాల్స్ అందించే సార్వత్రిక ఫోటో గుర్తింపు కార్డు.",
    "Register for Pehchan Card": "పెహచాన్ కార్డు కోసం నమోదు చేసుకోండి",
    "Gram Panchayat / CSC Biometric Authentication": "గ్రామ పంచాయతీ / CSC బయోమెట్రిక్ ప్రమాణీకరణ",
    "Verify your Aadhaar and artisanal trade through local CSC center or Village Officer.": "స్థానిక CSC కేంద్రం లేదా గ్రామ అధికారి ద్వారా మీ ఆధార్ మరియు హస్తకళ వ్యాపారాన్ని ధృవీకరించండి.",
    "Pehchan Card & PM Vishwakarma Certificate Issued": "పెహచాన్ కార్డు & పీఎం విశ్వకర్మ ధృవీకరణ పత్రం జారీ చేయబడింది",
    "Receive digital artisan ID card and official national certification from Ministry of MSME.": "MSME మంత్రిత్వ శాఖ నుండి డిజిటల్ గుర్తింపు కార్డు మరియు అధికారిక జాతీయ సర్టిఫికేట్ పొందండి.",
    "5-Day Skill Upgradation Workshop (₹500/Day Stipend)": "5-రోజుల నైపుణ్య శిక్షణ వర్క్‌షాప్ (రోజుకు ₹500 స్టైపెండ్)",
    "Attend modern toolkit training at your nearest Government Industrial Training Institute (ITI).": "మీ సమీప ప్రభుత్వ పారిశ్రామిక శిక్షణా సంస్థ (ITI) లో ఆధునిక టూల్‌కిట్ శిక్షణకు హాజరుకండి.",
    "₹15,000 E-Voucher for Handcraft Toolkit & Loom Parts": "హస్తకళ టూల్‌కిట్ & మగ్గం భాగాల కోసం ₹15,000 ఈ-వోచర్",
    "Direct DBT digital voucher credited to purchase certified handlooms, chisels, or pottery wheels.": "సర్టిఫైడ్ చేనేత మగ్గాలు, ఉలి లేదా కుండల చక్రాలు కొనుగోలు చేయడానికి ప్రత్యక్ష DBT డిజిటల్ వోచర్.",
    "₹3,00,000 Collateral-Free Enterprise Loan @ 5% Concessional Interest": "5% రాయితీ వడ్డీతో ₹3,00,000 పూచీకత్తు లేని వ్యాపార రుణం",
    "Tranche 1: ₹1,00,000 (18 months) + Tranche 2: ₹2,00,000 (30 months) backed by CGTMSE guarantee.": "విడత 1: ₹1,00,000 (18 నెలలు) + విడత 2: ₹2,00,000 (30 నెలలు) CGTMSE గ్యారెంటీతో.",
    "Seller-to-Seller Heritage Network": "కళాకారుల నుండి కళాకారుల వారసత్వ నెట్‌వర్క్",
    "Collaborate with Artisans": "తోటి కళాకారులతో సహకరించండి",
    "Connect with creators across India and build something together. Form inter-craft capsule collections, execute bespoke commissions, and revive ancestral art fusions.": "భారతదేశం అంతటా ఉన్న కళాకారులతో కనెక్ట్ అవ్వండి మరియు కలిసి సృష్టించండి. సంయుక్త కలెక్షన్‌లు రూపొందించండి మరియు పూర్వీకుల కళలను పునరుద్ధరించండి.",
