    "5th-generation master pit-loom weaver from Madanpura, Varanasi. Recipient of National Master Craftsperson Award for revival of antique Kadwa floral brocades.": "మదన్‌పురా, వారణాసికి చెందిన 5వ తరం మాస్టర్ పిట్-లూమ్ నేతన్న. పురాతన కడ్వా ఫ్లోరల్ బ్రొకేడ్ల పునరుద్ధరణకు జాతీయ అవార్డు గ్రహీత.",
    "Master Ikat tie-and-dye mathematician and master weaver from Bhoodan Pochampally. Renowned for complex double ikat chevrons and training over 80 rural women weavers.": "భూదాన్ పోచంపల్లికి చెందిన మాస్టర్ ఇక్కత్ టై-అండ్-డై గణిత నిపుణురాలు మరియు మాస్టర్ నేతకారిణి. సంక్లిష్ట డబుల్ ఇక్కత్ డిజైన్లకు ప్రసిద్ధి.",
    "State Awardee artist preserving the traditional Kohbar and Kachni line styles. Her paintings bring ancient ecological folklore to contemporary handmade bamboo-cotton surfaces.": "సంప్రదాయ కోహ్‌బర్ మరియు కచ్ని శైలులను పరిరక్షిస్తున్న రాష్ట్ర అవార్డు గ్రహీత. వెదురు-పత్తి ఉపరితలాలపై పురాతన జానపద కథలను చిత్రించే కళాకారిణి.",
    "Renowned 9th-generation natural dye master and Ajrakh block printer. Globally celebrated for reviving zero-chemical indigo and pomegranate natural mordants.": "ప్రఖ్యాత 9వ తరం సహజ రంగుల నిపుణుడు మరియు అజ్రఖ్ బ్లాక్ ప్రింటర్. రసాయన రహిత సహజ నీలిమందు పునరుద్ధరణకు ప్రపంచవ్యాప్తంగా ప్రసిద్ధి.",
    "Direct disciple of master Kripal Singh Shekhawat. Dedicated to preserving single-fire cobalt oxide ceramics and training next-generation studio potters.": "గురువు కృపాల్ సింగ్ షెకావత్ శిష్యుడు. కోబాల్ట్ ఆక్సైడ్ పింగాణీ కళను సంరక్షించడానికి మరియు తరువాతి తరం కుమ్మరులకు శిక్షణ ఇవ్వడానికి అంకితం.",
    "Tribal Master Metallurgist carrying forward 4,500-year-old Cire Perdue lost-wax casting. Recognized for majestic tribal processional elephants and folk deities.": "4,500 సంవత్సరాల పురాతన డోక్రా మైనపు కాస్టింగ్‌ను కొనసాగిస్తున్న గిరిజన మాస్టర్ మెటలర్జిస్ట్. గంభీరమైన ఏనుగులు మరియు జానపద దేవతలకు ప్రసిద్ధి.",
    "Master of the Kani loom and coded Talim scripts. Preserving authentic 100% Changthangi hand-spun pashmina without synthetic blending.": "కని మగ్గం మరియు తాలీమ్ స్క్రిప్ట్ నిపుణుడు. ఎటువంటి కృత్రిమ పదార్థాలు కలపకుండా 100% స్వచ్ఛమైన చేతితో నేసిన పష్మినాను పరిరక్షిస్తున్నారు.",
