    "The Pride of Telangana": "தெலுங்கானாவின் பெருமை",
    "Famous for its intricate tie-and-dye technique, Pochampally Ikat is known for its geometric patterns and vibrant colours. Each piece is a result of precise planning, traditional skill and generations of expertise.": "சிக்கலான டை-அண்ட்-டை நுட்பத்திற்கு பெயர் பெற்ற போச்சம்பள்ளி இக்கத், அதன் வடிவியல் வடிவங்கள் மற்றும் துடிப்பான வண்ணங்களுக்கு பெயர் பெற்றது. ஒவ்வொரு படைப்பும் துல்லியமான திட்டமிடல், பாரம்பரிய திறன் மற்றும் தலைமுறை நிபுணத்துவத்தின் விளைவாகும்.",
