    "Mathematical double ikat tie-and-dye handwoven on manual tension pit-looms in Bhoodan Pochampally village. Both warp and weft yarns are pre-calculated, bundled, and dipped in living botanical indigofera and alizarin madder vats to create razor-sharp geometric chevron and diamond motifs. Certified GI craft of Telangana.": "பூதான் போச்சம்பள்ளி கிராமத்தில் பாரம்பரிய குழி தறிகளில் கைநெசவு செய்யப்பட்ட கணித துல்லியம் கொண்ட டபுள் இக்கத் டை-அண்ட்-டை புடவை. பாவு மற்றும் ஊடை இழைகள் முன்கூட்டியே கணக்கிடப்பட்டு, கட்டப்பட்டு, இயற்கை இண்டிகோ மற்றும் மஞ்சிட்டி சாய தொட்டிகளில் முக்கி எடுக்கப்பட்டு கூர்மையான வடிவியல் வைர உருவங்கள் உருவாக்கப்படுகின்றன. தெலுங்கானாவின் சான்றளிக்கப்பட்ட புவிசார் குறியீடு கைவினை.",
