    "The weight of the electroplated silver Zari on pure mulberry Katan silk is magnificent. Examining the reverse side confirms authentic Kadwa tapestry weaving with zero loose floating threads. The Digital Craft Passport and QR seal match the official UP GI register perfectly.": "தூய மல்பெரி கட்டான் பட்டில் மின்முலாம் பூசப்பட்ட வெள்ளி ஜரிகையின் எடையும் நேர்த்தியும் அற்புதமாக உள்ளது. பின்பக்கத்தை பரிசோதிக்கும் போது எந்த தளர்வான நூல்களும் இல்லாமல் உண்மையான கட்வா நெசவு முறை உறுதிப்படுத்தப்படுகிறது. டிஜிட்டல் கிராஃப்ட் பாஸ்போர்ட் மற்றும் கியூஆர் முத்திரை உ.பி.யின் அதிகாரப்பூர்வ ஜிஐ பதிவேட்டுடன் சரியாக பொருந்துகிறது.",
