    "Preserving 5,000 Years of Indian Craft Heritage": "5,000 ஆண்டுகால இந்திய கைவினைப் பாரம்பரியத்தைப் பாதுகாத்தல்",
    "Bridging ancestral Indian GI artisan clusters with conscious global patrons through verifiable digital craft passports and living heritage AI.": "சரிபார்க்கக்கூடிய டிஜிட்டல் கைவினை கடவுச்சீட்டுகள் மற்றும் நேரடி பாரம்பரிய AI மூலம் பூர்வீக இந்திய GI கைவினைஞர் குழுக்களை விழிப்புணர்வுள்ள உலகளாவிய புரவலர்களுடன் இணைக்கிறது.",
