    "Urban buyers seeking breathable natural dyes for festive wear. Combine natural indigo with mustard yellow or madder red.": "நகர்ப்புற வாங்குவோர் பண்டிகை ஆடைகளுக்கு இயற்கை சாயங்களைத் தேடுகிறார்கள். இயற்கை அவுரியை கடுகு மஞ்சள் அல்லது மஞ்சிஷ்டா சிவப்புடன் இணைக்கவும்.",
    "Use Deblurred Photo": "மங்கல் நீக்கப்பட்ட புகைப்படத்தைப் பயன்படுத்து",
