    "West India": "மேற்கு இந்தியா",
    "When other master artisans propose collaborations with your craft, their requests will appear here for review.": "மற்ற கைவினைஞர்கள் உங்கள் கைவினையுடன் ஒத்துழைப்பை முன்மொழிகையில், அவர்களின் கோரிக்கைகள் மதிப்பாய்வுக்காக இங்கே தோன்றும்.",
    "Year-round New Home Griha Pravesh season": "ஆண்டு முழுவதும் புதிய இல்ல கிரகப்பிரவேச காலம்",
    "Years of Mastery": "கைதேர்ந்த ஆண்டுகள்",
