    "e.g. Kadwa Silk & Cast Bell Metal Minaudière Clutches": "எ.கா. கட்வா பட்டு & வெண்கல கைப்பை",
    "e.g. Pure Katan Silk Handwoven Kadwa Zari Saree": "எ.கா. தூய கடான் பட்டு கைத்தறி கட்வா ஜரி சேலை",
    "giving the artisan only ~25-35%. On Desi Craft, you receive 100% of fair customer value directly.": "கைவினைஞருக்கு ~25-35% மட்டுமே கிடைக்கிறது. தேசி கிராஃப்டில் நீங்கள் 100% நியாயமான வாடிக்கையாளர் மதிப்பை நேரடியாகப் பெறுவீர்கள்.",
    "is now live on your artisan storefront with verified authenticity credentials.": "சரிபார்க்கப்பட்ட உண்மைத்தன்மை சான்றுகளுடன் இப்போது உங்கள் கைவினைஞர் முகப்பில் நேரலையில் உள்ளது.",
