    "Registered master artisans can claim free retail stalls at major international airports, railway terminals, and embassies globally.": "பதிவுசெய்த முதன்மை கைவினைஞர்கள் முக்கிய சர்வதேச விமான நிலையங்கள், ரயில் நிலையங்கள் மற்றும் தூதரகங்களில் இலவச சில்லறை விற்பனை அரங்குகளைப் பெறலாம்.",
    "Check District Product Catalog": "மாவட்ட தயாரிப்பு பட்டியலை சரிபார்க்கவும்",
