    "Universal photo identity card granting free health insurance under Ayushman Bharat and direct stall allotment at Dilli Haat and Surajkund Mela.": "ஆயுஷ்மான் பாரத்தின் கீழ் இலவச மருத்துவ காப்பீடு மற்றும் டெல்லி ஹாட், சூரஜ்குண்ட் மேளாவில் நேரடி அரங்கு ஒதுக்கீடு வழங்கும் தேசிய அடையாள அட்டை.",
