    "Verify your Aadhaar and artisanal trade through local CSC center or Village Officer.": "உள்ளூர் CSC மையம் அல்லது கிராம அதிகாரி மூலம் உங்கள் ஆதார் மற்றும் கைவினைத் தொழிலை சரிபார்க்கவும்.",
    "Pehchan Card & PM Vishwakarma Certificate Issued": "பெஹ்சான் அட்டை & பிஎம் விஸ்வகர்மா சான்றிதழ் வழங்கப்பட்டது",
    "Receive digital artisan ID card and official national certification from Ministry of MSME.": "MSME அமைச்சகத்திடமிருந்து டிஜிட்டல் அடையாள அட்டை மற்றும் அதிகாரப்பூர்வ தேசிய சான்றிதழைப் பெறுங்கள்.",
    "5-Day Skill Upgradation Workshop (₹500/Day Stipend)": "5 நாள் திறன் மேம்பாட்டு பட்டறை (நாள் ஒன்றுக்கு ₹500 உதவித்தொகை)",
    "Attend modern toolkit training at your nearest Government Industrial Training Institute (ITI).": "உங்கள் அருகிலுள்ள அரசு தொழிற்பயிற்சி நிறுவனத்தில் (ITI) நவீன கருவிகள் பயிற்சியில் பங்கேற்கவும்.",
    "₹15,000 E-Voucher for Handcraft Toolkit & Loom Parts": "கைவினை கருவிகள் மற்றும் தறி பாகங்களுக்கு ₹15,000 இ-வவுச்சர்",
    "Direct DBT digital voucher credited to purchase certified handlooms, chisels, or pottery wheels.": "சான்றளிக்கப்பட்ட கைத்தறி, உளி அல்லது குயவர் சக்கரங்களை வாங்க நேரடி DBT டிஜிட்டல் வவுச்சர்.",
    "₹3,00,000 Collateral-Free Enterprise Loan @ 5% Concessional Interest": "5% சலுகை வட்டியில் ₹3,00,000 பிணையில்லா தொழில் கடன்",
    "Tranche 1: ₹1,00,000 (18 months) + Tranche 2: ₹2,00,000 (30 months) backed by CGTMSE guarantee.": "தவணை 1: ₹1,00,000 (18 மாதங்கள்) + தவணை 2: ₹2,00,000 (30 மாதங்கள்) CGTMSE உத்தரவாதத்துடன்.",
