    "Instructor": "ಬೋಧಕರು",
    "spots remaining": "ಸ್ಥಳಗಳು ಉಳಿದಿವೆ",
    "Mathematical double ikat tie-and-dye handwoven on manual tension pit-looms in Bhoodan Pochampally village. Both warp and weft yarns are pre-calculated, bundled, and dipped in living botanical indigofera and alizarin madder vats to create razor-sharp geometric chevron and diamond motifs. Certified GI craft of Telangana.": "ಭೂದಾನ್ ಪೋಚಂಪಲ್ಲಿ ಹಳ್ಳಿಯಲ್ಲಿ ಸಾಂಪ್ರದಾಯಿಕ ಗುಂಡಿ ಮಗ್ಗಗಳಲ್ಲಿ ಕೈಯಿಂದ ನೇಯ್ದ ಗಣಿತದ ನಿಖರತೆಯ ಡಬಲ್ ಇಕ್ಕತ್ ಟೈ-ಅಂಡ್-ಡೈ ಸೀರೆ. ವಾರ್ಪ್ ಮತ್ತು ವೆಫ್ಟ್ ರೇಷ್ಮೆ ದಾರಗಳನ್ನು ಮೊದಲೇ ಲೆಕ್ಕಹಾಕಿ, ಕಟ್ಟಿ, ನೈಸರ್ಗಿಕ ಇಂಡಿಗೋ ಮತ್ತು ಮಂಜಿಷ್ಟ ಬಣ್ಣದ ಪಾತ್ರೆಗಳಲ್ಲಿ ಅದ್ದಿ ಅತ್ಯಂತ ತೀಕ್ಷ್ಣವಾದ ಜ್ಯಾಮಿತೀಯ ಮಾದರಿಗಳನ್ನು ರಚಿಸಲಾಗುತ್ತದೆ. ತೆಲಂಗಾಣದ ಅಧಿಕೃತ ಜಿಐ ಕರಕುಶಲ ಕಲೆ.",
    "Chitiki Double Ikat Mathematical Tie-and-Dye Weaving on Manual Pit Looms": "ಮ್ಯಾನುಯಲ್ ಪಿಟ್ ಲೂಮ್‌ಗಳಲ್ಲಿ ಚಿಟಿಕಿ ಡಬಲ್ ಇಕ್ಕತ್ ಗಣಿತದ ಟೈ-ಅಂಡ್-ಡೈ ನೇಯ್ಗೆ",
