    "The weight of the electroplated silver Zari on pure mulberry Katan silk is magnificent. Examining the reverse side confirms authentic Kadwa tapestry weaving with zero loose floating threads. The Digital Craft Passport and QR seal match the official UP GI register perfectly.": "ಶುದ್ಧ ಮಲ್ಬರಿ ಕಟಾನ್ ರೇಷ್ಮೆಯ ಮೇಲೆ ಎಲೆಕ್ಟ್ರೋಪ್ಲೇಟೆಡ್ ಬೆಳ್ಳಿ ಜರಿಯ ತೂಕ ಮತ್ತು ಶ್ರೇಷ್ಠತೆ ಅದ್ಭುತವಾಗಿದೆ. ಹಿಂಭಾಗವನ್ನು ಪರಿಶೀಲಿಸಿದಾಗ ಯಾವುದೇ ಸಡಿಲವಾದ ತೇಲುವ ಎಳೆಗಳಿಲ್ಲದೆ ಅಧಿಕೃತ ಕಡ್ವಾ ನೇಯ್ಗೆಯನ್ನು ಖಚಿತಪಡಿಸುತ್ತದೆ. ಡಿಜಿಟಲ್ ಕ್ರಾಫ್ಟ್ ಪಾಸ್‌ಪೋರ್ಟ್ ಮತ್ತು ಕ್ಯೂಆರ್ ಸೀಲ್ ಅಧಿಕೃತ ಯುಪಿ ಜಿಐ ನೋಂದಣಿಗೆ ಸಂಪೂರ್ಣವಾಗಿ ಹೊಂದಿಕೆಯಾಗುತ್ತದೆ.",
    "12 February 2026": "12 ಫೆಬ್ರವರಿ 2026",
    "Arjun Nambiar": "ಅರ್ಜುನ್ ನಂಬಿಯಾರ್",
    "Bengaluru, Karnataka": "ಬೆಂಗಳೂರು, ಕರ್ನಾಟಕ",
    "Shipped directly from the master weaver’s loom in Varanasi within 4 business days. Knowing that 82% of the price went directly to the artisan family without boutique commissions makes this purchase deeply fulfilling.": "ವಾರಣಾಸಿಯ ಮಾಸ್ಟರ್ ನೇಕಾರರ ಮಗ್ಗದಿಂದ ನೇರವಾಗಿ 4 ಕೆಲಸದ ದಿನಗಳಲ್ಲಿ ರವಾನಿಸಲಾಗಿದೆ. ಬೊಟಿಕ್ ಕಮಿಷನ್‌ಗಳಿಲ್ಲದೆ ಬೆಲೆಯ 82% ನೇರವಾಗಿ ಕುಶಲಕರ್ಮಿಗಳ ಕುಟುಂಬಕ್ಕೆ ತಲುಪಿದೆ ಎಂದು ತಿಳಿಯುವುದು ಈ ಖರೀದಿಯನ್ನು ತೃಪ್ತಿಕರವಾಗಿಸುತ್ತದೆ.",
