    "Jammu & Kashmir": "ಜಮ್ಮು & ಕಾಶ್ಮೀರ",
    "5th-generation master pit-loom weaver from Madanpura, Varanasi. Recipient of National Master Craftsperson Award for revival of antique Kadwa floral brocades.": "ಮದನ್‌ಪುರ, ವಾರಣಾಸಿಯ 5ನೇ ತಲೆಮಾರಿನ ನೇಕಾರರು. ಪುರಾತನ ಕಡ್ವಾ ಬ್ರೊಕೇಡ್‌ಗಳ ಪುನರುಜ್ಜೀವನಕ್ಕಾಗಿ ರಾಷ್ಟ್ರೀಯ ಪ್ರಶಸ್ತಿ ಪುರಸ್ಕೃತರು.",
    "Master Ikat tie-and-dye mathematician and master weaver from Bhoodan Pochampally. Renowned for complex double ikat chevrons and training over 80 rural women weavers.": "ಭೂದಾನ್ ಪೋಚಂಪಲ್ಲಿಯ ನುರಿತ ಇಕ್ಕತ್ ನೇಕಾರರು. ಸಂಕೀರ್ಣ ಡಬಲ್ ಇಕ್ಕತ್ ವಿನ್ಯಾಸಗಳು ಮತ್ತು 80ಕ್ಕೂ ಹೆಚ್ಚು ಮಹಿಳೆಯರಿಗೆ ತರಬೇತಿ ನೀಡಿದ ಖ್ಯಾತಿ.",
    "State Awardee artist preserving the traditional Kohbar and Kachni line styles. Her paintings bring ancient ecological folklore to contemporary handmade bamboo-cotton surfaces.": "ಸಾಂಪ್ರದಾಯಿಕ ಕೋಹಬರ್ ಮತ್ತು ಕಚ್ನಿ ಶೈಲಿಗಳನ್ನು ಸಂರಕ್ಷಿಸುವ ರಾಜ್ಯ ಪ್ರಶಸ್ತಿ ಪುರಸ್ಕೃತೆ. ಬಿದಿರು-ಹತ್ತಿ ಹಾಳೆಗಳ ಮೇಲೆ ಜಾನಪದ ಚಿತ್ರ ಬಿಡಿಸುವ ಕಲಾವಿದೆ.",
    "Renowned 9th-generation natural dye master and Ajrakh block printer. Globally celebrated for reviving zero-chemical indigo and pomegranate natural mordants.": "ಪ್ರಸಿದ್ಧ 9ನೇ ತಲೆಮಾರಿನ ನೈಸರ್ಗಿಕ ಬಣ್ಣ ತಜ್ಞ ಮತ್ತು ಅಜ್ರಖ್ ಮುದ್ರಕ. ರಾಸಾಯನಿಕ ರಹಿತ ಬಣ್ಣಗಳ ಪುನರುಜ್ಜೀವನಕ್ಕಾಗಿ ಜಾಗತಿಕವಾಗಿ ಪ್ರಸಿದ್ಧರು.",
    "Direct disciple of master Kripal Singh Shekhawat. Dedicated to preserving single-fire cobalt oxide ceramics and training next-generation studio potters.": "ಗುರು ಕೃಪಾಲ್ ಸಿಂಗ್ ಶೇಖಾವತ್ ಅವರ ನೇರ ಶಿಷ್ಯ. ಕೋಬಾಲ್ಟ್ ಆಕ್ಸೈಡ್ ಪಿಂಗಾಣಿ ಕಲೆ ಸಂರಕ್ಷಿಸಲು ಮುಂದಿನ ಪೀಳಿಗೆಗೆ ತರಬೇತಿ ನೀಡುವಲ್ಲಿ ನಿರತರು.",
    "Tribal Master Metallurgist carrying forward 4,500-year-old Cire Perdue lost-wax casting. Recognized for majestic tribal processional elephants and folk deities.": "4,500 ವರ್ಷಗಳ ಪುರಾತನ ಕಳೆದುಹೋದ ಮೇಣದ ಎರಕಹೊಯ್ಯುವ ಕಲೆ ಮುಂದುವರಿಸುತ್ತಿರುವ ಬುಡಕಟ್ಟು ಲೋಹಶಿಲ್ಪಿ. ಗಂಭೀರ ಆನೆಗಳು ಮತ್ತು ಜಾನಪದ ದೇವತೆಗಳಿಗೆ ಪ್ರಸಿದ್ಧರು.",
    "Master of the Kani loom and coded Talim scripts. Preserving authentic 100% Changthangi hand-spun pashmina without synthetic blending.": "ಕಾನಿ ಮಗ್ಗ ಮತ್ತು ತಾಲೀಮ್ ಲಿಪಿಯ ಪರಿಣತರು. ಯಾವುದೇ ಕೃತಕ ಮಿಶ್ರಣವಿಲ್ಲದೆ 100% ಶುದ್ಧ ಚಾಂಗ್‌ಥಾಂಗಿ ಕೈನೇಯ್ಗೆಯ ಪಶ್ಮಿನಾವನ್ನು ಸಂರಕ್ಷಿಸುತ್ತಿದ್ದಾರೆ.",
    "Kadwa Weaving": "ಕಡ್ವಾ ನೇಯ್ಗೆ",
