    "Ancient Indigo Vat Fermentation": "ಪುರಾತನ ಇಂಡಿಗೊ ತೊಟ್ಟಿ ಹುದುಗುವಿಕೆ",
    "Carved Teak Block Registration": "ಕೆತ್ತಿದ ತೇಗದ ಬ್ಲಾಕ್ ಹೊಂದಾಣಿಕೆ",
    "Clayless Quartz Dough Kneading": "ಮಣ್ಣಿಲ್ಲದ ಕ್ವಾರ್ಟ್ಜ್ ಹಿಟ್ಟು ಬೆರೆಸುವುದು",
    "Squirrel Hair Brush Painting": "ಅಳಿಲು ಕೂದಲಿನ ಬ್ರಷ್ ಚಿತ್ರಕಲೆ",
    "Cobalt & Copper Oxide Formulation": "ಕೋಬಾಲ್ಟ್ & ತಾಮ್ರದ ಆಕ್ಸೈಡ್ ತಯಾರಿಕೆ",
    "Cire Perdue Lost-Wax Modeling": "ಕಳೆದುಹೋದ ಮೇಣದ ಮಾದರಿ ತಯಾರಿಕೆ",
    "Beeswax Wire Extrusion": "ಜೇನುಮೇಣದ ತಂತಿ ಎಳೆಯುವಿಕೆ",
    "Clay Core Molding": "ಮಣ್ಣಿನ ಒಳಭಾಗದ ಅಚ್ಚು",
