    "Mathematical double ikat tie-and-dye handwoven on manual tension pit-looms in Bhoodan Pochampally village. Both warp and weft yarns are pre-calculated, bundled, and dipped in living botanical indigofera and alizarin madder vats to create razor-sharp geometric chevron and diamond motifs. Certified GI craft of Telangana.": "ഭൂദാൻ പോച്ചംപള്ളി ഗ്രാമത്തിലെ പരമ്പരാഗത പിറ്റ്-ലൂമുകളിൽ കൈകൊണ്ട് നെയ്ത ഗണിതശാസ്ത്ര കൃത്യതയുള്ള ഡബിൾ ഇക്കത്ത് ടൈ-ആൻഡ്-ഡൈ സാരി. വാർപ്പും വെഫ്റ്റും നൂലുകൾ മുൻകൂട്ടി കണക്കാക്കി, കെട്ടി, സ്വാഭാവിക ഇൻഡിഗോഫെറ, അലിസാരിൻ മാഡർ ചായങ്ങളിൽ മുക്കി മൂർച്ചയുള്ള ജ്യാമിതീയ പാറ്റേണുകൾ സൃഷ്ടിക്കുന്നു. തെലങ്കാനയുടെ സാക്ഷ്യപ്പെടുത്തിയ ജിഐ കരകൗശലം.",
    "Chitiki Double Ikat Mathematical Tie-and-Dye Weaving on Manual Pit Looms": "കൈത്തറി പിറ്റ് ലൂമുകളിൽ ചിറ്റിക്കി ഡബിൾ ഇക്കത്ത് ഗണിത ടൈ-ആൻഡ്-ഡൈ നെയ്ത്ത്",
