    "Jammu & Kashmir": "ജമ്മു & കശ്മീർ",
    "5th-generation master pit-loom weaver from Madanpura, Varanasi. Recipient of National Master Craftsperson Award for revival of antique Kadwa floral brocades.": "വാരാണസിയിലെ മദൻപുരയിൽ നിന്നുള്ള 5-ാം തലമുറയിലെ നെയ്ത്തുകാരൻ. പുരാതന കഡ്വ ബ്രോക്കേഡ് പുനരുജ്ജീവിപ്പിച്ചതിന് ദേശീയ അവാർഡ് ജേതാവ്.",
    "Master Ikat tie-and-dye mathematician and master weaver from Bhoodan Pochampally. Renowned for complex double ikat chevrons and training over 80 rural women weavers.": "ഭൂദാൻ പോച്ചമ്പള്ളിയിലെ മാസ്റ്റർ ഇക്കത്ത് നെയ്ത്തുകാരി. സങ്കീർണ്ണമായ ഡബിൾ ഇക്കത്ത് ഡിസൈനുകൾക്ക് പേരുകേട്ട വിദഗ്ദ്ധ.",
    "State Awardee artist preserving the traditional Kohbar and Kachni line styles. Her paintings bring ancient ecological folklore to contemporary handmade bamboo-cotton surfaces.": "പരമ്പരാഗത കോഹ്ബർ, കച്ച്നി ശൈലികൾ സംരക്ഷിക്കുന്ന സംസ്ഥാന അവാർഡ് ജേതാവ്. പ്രകൃതിദത്ത പ്രതലങ്ങളിൽ പുരാതന നാടോടിക്കഥകൾ വരയ്ക്കുന്നു.",
    "Renowned 9th-generation natural dye master and Ajrakh block printer. Globally celebrated for reviving zero-chemical indigo and pomegranate natural mordants.": "പ്രശസ്തനായ 9-ാം തലമുറയിലെ പ്രകൃതിദത്ത ചായക്കൂട്ടുകാരനും അജ്‌റഖ് ബ്ലോക്ക് പ്രിന്ററും. രാസവസ്തുക്കളില്ലാത്ത ചായങ്ങളുടെ പുനരുജ്ജീവനത്തിന് പേരുകേട്ടയാൾ.",
    "Direct disciple of master Kripal Singh Shekhawat. Dedicated to preserving single-fire cobalt oxide ceramics and training next-generation studio potters.": "മാസ്റ്റർ കൃപാൽ സിംഗ് ശെഖാവത്തിന്റെ നേരിട്ടുള്ള ശിഷ്യൻ. കോബാൾട്ട് ഓക്സൈഡ് സെറാമിക്സ് സംരക്ഷിക്കുന്നതിനായി പ്രവർത്തിക്കുന്ന വിദഗ്ദ്ധൻ.",
    "Tribal Master Metallurgist carrying forward 4,500-year-old Cire Perdue lost-wax casting. Recognized for majestic tribal processional elephants and folk deities.": "4,500 വർഷം പഴക്കമുള്ള മെഴുക് കാസ്റ്റിംഗ് രീതി മുന്നോട്ട് കൊണ്ടുപോകുന്ന ഗോത്രവർഗ്ഗ മാസ്റ്റർ. ഗംഭീരമായ ആനകൾക്കും നാടോടി ദൈവങ്ങൾക്കും പേരുകേട്ടയാൾ.",
    "Master of the Kani loom and coded Talim scripts. Preserving authentic 100% Changthangi hand-spun pashmina without synthetic blending.": "കനി തറിയുടെയും താലിം ലിപിയുടെയും മാസ്റ്റർ. കൃത്രിമ ചേരുവകളില്ലാതെ 100% ശുദ്ധമായ കശ്മീരി പഷ്മിന സംരക്ഷിക്കുന്നു.",
    "Kadwa Weaving": "കഡ്വ നെയ്ത്ത്",
