    "Mathematical double ikat tie-and-dye handwoven on manual tension pit-looms in Bhoodan Pochampally village. Both warp and weft yarns are pre-calculated, bundled, and dipped in living botanical indigofera and alizarin madder vats to create razor-sharp geometric chevron and diamond motifs. Certified GI craft of Telangana.": "भूदान पोचमपल्ली गावात पारंपारिक खड्डा माग (पिट लूम) वर हाताने विणलेली गणितीय अचूकतेची डबल इकत टाय-अँड-डाई साडी. ताणा आणि बाणा दोन्ही धागे आधी मोजले जातात, बांधले जातात आणि अस्सल नैसर्गिक नीळ आणि मजीठच्या रंगात बुडवून तीक्ष्ण भौमितिक नक्षी तयार केली जाते. तेलंगणाची प्रमाणित जीआय हस्तकला.",
