    "5th-generation master pit-loom weaver from Madanpura, Varanasi. Recipient of National Master Craftsperson Award for revival of antique Kadwa floral brocades.": "मदनपुरा, वाराणसी येथील ५व्या पिढीतील विणकर. प्राचीन कडवा फ्लोरल ब्रोकेड पुनरुज्जीवनासाठी राष्ट्रीय पुरस्कार विजेते.",
    "Master Ikat tie-and-dye mathematician and master weaver from Bhoodan Pochampally. Renowned for complex double ikat chevrons and training over 80 rural women weavers.": "भूदान पोचमपल्ली येथील मास्टर इकत विणकर. दुहेरी इकत शेवरॉन आणि ८० हून अधिक महिला विणकरांना प्रशिक्षित करण्यासाठी प्रसिद्ध.",
    "State Awardee artist preserving the traditional Kohbar and Kachni line styles. Her paintings bring ancient ecological folklore to contemporary handmade bamboo-cotton surfaces.": "पारंपारिक कोहबर आणि कचनी रेषा शैलींचे जतन करणाऱ्या राज्य पुरस्कार विजेत्या कलाकार. बांबू-सुती कापडावर लोककथा साकारतात.",
    "Renowned 9th-generation natural dye master and Ajrakh block printer. Globally celebrated for reviving zero-chemical indigo and pomegranate natural mordants.": "प्रसिद्ध ९व्या पिढीतील नैसर्गिक रंगतज्ज्ञ आणि अजरख ब्लॉक प्रिंटर. रसायनमुक्त नीळ आणि नैसर्गिक घटकांच्या पुनरुज्जीवनासाठी जगभर प्रसिद्ध.",
    "Direct disciple of master Kripal Singh Shekhawat. Dedicated to preserving single-fire cobalt oxide ceramics and training next-generation studio potters.": "मास्टर कृपाल सिंग शेखावत यांचे थेट शिष्य. कोबाल्ट ऑक्साईड सिरेमिक्सचे जतन आणि पुढच्या पिढीला प्रशिक्षण देण्यासाठी समर्पित.",
    "Tribal Master Metallurgist carrying forward 4,500-year-old Cire Perdue lost-wax casting. Recognized for majestic tribal processional elephants and folk deities.": "४,५०० वर्षे जुन्या मेणाच्या साच्यातील धातूकामाचा वारसा चालवणारे आदिवासी धातूशिल्पी. भव्य हत्ती आणि लोकदेवतांच्या मूर्तींसाठी ओळखले जातात.",
    "Master of the Kani loom and coded Talim scripts. Preserving authentic 100% Changthangi hand-spun pashmina without synthetic blending.": "कानी माग आणि तालीम लिपीचे उस्ताद. कोणतेही कृत्रिम मिश्रण नसलेले अस्सल १००% चांगथांगी हातमाग पश्मिना जपणारे कारागीर.",
    "Kadwa Weaving": "कडवा विणकाम",
