    "Namaste Lakshmi ji! Looking forward to creating our joint collection combining your Pochampally double ikat with our Kadwa zari weaving.": "नमस्ते लक्ष्मी जी! तुमचे पोचमपल्ली डबल इकत आणि आमचे कडवा जरी विणकाम एकत्र करून संयुक्त संग्रह तयार करण्यास उत्सुक आहे.",
    "Namaskaram Rajeshwar ji! It is an honor. I have tied the warp clusters for the chevron borders with natural indigo and madder root.": "नमस्कार रामेश्वर जी! हा माझा सन्मान आहे. मी नैसर्गिक नीळ आणि मँडर मुळांसह शेवरॉन बॉर्डरसाठी ताणा बांधला आहे.",
    "The natural indigo dyed warp samples arrived in Varanasi! The geometric alignment is superb.": "नैसर्गिक नीळ रंगवलेल्या ताण्याचे नमुने वाराणसीमध्ये पोहोचले! भौमितिक जुळणी उत्कृष्ट आहे.",
    "Sharing the workshop address in Pochampally where our master weavers are preparing the warp frames.": "पोचमपल्ली येथील कार्यशाळेचा पत्ता शेअर करत आहे जिथे आमचे विणकर ताणा फ्रेम तयार करत आहेत.",
    "Pochampally Ikat Weavers Colony": "पोचमपल्ली इकत विणकर वसाहत",
    "Here is our Kadwa Floral Zari border pattern draft for our festive stole collection.": "आमच्या उत्सव स्टोल संग्रहासाठी कडवा फ्लोरल जरी बॉर्डर पॅटर्न ड्राफ्ट येथे आहे.",
    "Dr. Khatri ji, I dispatched two meters of handspun Katan silk for the pilot Ajrakh block printing test.": "डॉ. खत्री जी, मी चाचणी अजरख ब्लॉक छपाईसाठी दोन मीटर हातमागावरील कातान रेशीम पाठवले आहे.",
    "Namaste Rajeshwar ji, I received your silk swatches. I will prepare the pomegranate mordant vat tomorrow.": "नमस्ते राजेश्वर जी, मला तुमचे रेशमाचे नमुने मिळाले. मी उद्या डाळिंबाच्या नैसर्गिक रंगाची टाकी तयार करेन.",
