    "Mathematical double ikat tie-and-dye handwoven on manual tension pit-looms in Bhoodan Pochampally village. Both warp and weft yarns are pre-calculated, bundled, and dipped in living botanical indigofera and alizarin madder vats to create razor-sharp geometric chevron and diamond motifs. Certified GI craft of Telangana.": "ভূদান পোচমপল্লী গ্রামে ঐতিহ্যবাহী পিট-লুমে হাতে বোনা গাণিতিক নির্ভুলতার ডাবল ইকত টাই-অ্যান্ড-ডাই শাড়ি। টানা এবং পড়েন উভয় সুতো আগে থেকেই গণনা করে, গুচ্ছ বেঁধে প্রাকৃতিক নীল ও মঞ্জিষ্ঠার রসে ডুবিয়ে ধারালো জ্যামিতিক নকশা তৈরি করা হয়। তেলেঙ্গানার প্রত্যয়িত জিআই কারুশিল্প।",
