    "The weight of the electroplated silver Zari on pure mulberry Katan silk is magnificent. Examining the reverse side confirms authentic Kadwa tapestry weaving with zero loose floating threads. The Digital Craft Passport and QR seal match the official UP GI register perfectly.": "খাঁটি তুঁত কাতান সিল্কে রূপালী জরির ওজন এবং অনুভূতি চমৎকার। উল্টো পিঠ পরীক্ষা করলে কোনো আলগা সুতো ছাড়া খাঁটি কড়ওয়া বয়ন স্পষ্ট বোঝা যায়। ডিজিটাল ক্রাফট পাসপোর্ট এবং কিউআর সিল অফিসিয়াল ইউপি জিআই নিবন্ধনের সাথে নিখুঁতভাবে মেলে।",
    "12 February 2026": "১২ ফেব্রুয়ারি ২০২৬",
