    "5th-generation master pit-loom weaver from Madanpura, Varanasi. Recipient of National Master Craftsperson Award for revival of antique Kadwa floral brocades.": "বারাণসীর মদনপুরার ৫ম প্রজন্মের মাস্টার তাঁতি। প্রাচীন কাদওয়া ব্রোকেড পুনরুজ্জীবনের জন্য জাতীয় পুরস্কারপ্রাপ্ত।",
    "Master Ikat tie-and-dye mathematician and master weaver from Bhoodan Pochampally. Renowned for complex double ikat chevrons and training over 80 rural women weavers.": "ভূদান পোচমপল্লীর দক্ষ ইকত টাই-অ্যান্ড-ডাই তাঁতি। জটিল ডাবল ইকত এবং ৮০ জনের বেশি গ্রামীণ নারীকে প্রশিক্ষণের জন্য খ্যাত।",
    "State Awardee artist preserving the traditional Kohbar and Kachni line styles. Her paintings bring ancient ecological folklore to contemporary handmade bamboo-cotton surfaces.": "ঐতিহ্যবাহী কোহবার এবং কচনি শৈলী সংরক্ষণকারী রাজ্য পুরস্কারপ্রাপ্ত শিল্পী। বাঁশ-সুতির পৃষ্ঠে প্রাচীন লোককথা ফুটিয়ে তোলেন।",
    "Renowned 9th-generation natural dye master and Ajrakh block printer. Globally celebrated for reviving zero-chemical indigo and pomegranate natural mordants.": "বিখ্যাত ৯ম প্রজন্মের প্রাকৃতিক রঞ্জক বিশেষজ্ঞ ও আজরখ ব্লক প্রিন্টার। রাসায়নিকমুক্ত নীল ও প্রাকৃতিক রঙের ব্যবহারের জন্য আন্তর্জাতিকভাবে প্রশংসিত।",
    "Direct disciple of master Kripal Singh Shekhawat. Dedicated to preserving single-fire cobalt oxide ceramics and training next-generation studio potters.": "গুরু কৃপাল সিং শেখাওয়াতের সরাসরি শিষ্য। কোবাল্ট অক্সাইড সিরামিক সংরক্ষণ ও পরবর্তী প্রজন্মকে প্রশিক্ষণে নিবেদিতপ্রাণ।",
    "Tribal Master Metallurgist carrying forward 4,500-year-old Cire Perdue lost-wax casting. Recognized for majestic tribal processional elephants and folk deities.": "৪,৫০০ বছরের প্রাচীন হারিয়ে যাওয়া মোম ঢালাই শিল্প বহনকারী আদিবাসী ধাতুশিল্পী। রাজকীয় হাতি ও লোকদেবতার মূর্তির জন্য খ্যাত।",
    "Master of the Kani loom and coded Talim scripts. Preserving authentic 100% Changthangi hand-spun pashmina without synthetic blending.": "কানি তাঁত এবং তালিম লিপির মাস্টার। কৃত্রিম মিশ্রণ ছাড়াই খাঁটি ১০০% চাংথাঙ্গি হাতে কাটা পশমিনা সংরক্ষণকারী।",
