    "Royal Kadwa x Pochampally Ikat Festive Stoles": "রয়্যাল কাদওয়া x পোচমপল্লী ইকত উৎসব স্টোল",
    "Ajrakh Natural Indigo Dyed Brocade Yardage": "আজরখ প্রাকৃতিক নীল রঞ্জিত ব্রোকেড থান",
    "Namaste Lakshmi ji! Looking forward to creating our joint collection combining your Pochampally double ikat with our Kadwa zari weaving.": "নমস্তে লক্ষ্মী জি! আপনার পোচমপল্লী ডাবল ইকত এবং আমাদের কাদওয়া জরি বুনন একত্রিত করে যৌথ সংগ্রহ তৈরির অপেক্ষায় আছি।",
    "Namaskaram Rajeshwar ji! It is an honor. I have tied the warp clusters for the chevron borders with natural indigo and madder root.": "নমস্কার রামেশ্বর জি! এটি অত্যন্ত সম্মানের। আমি প্রাকৃতিক নীল এবং মঞ্জিষ্ঠা দিয়ে পাড়ের জন্য টানা বেঁধে ফেলেছি।",
    "The natural indigo dyed warp samples arrived in Varanasi! The geometric alignment is superb.": "প্রাকৃতিক নীলে রঞ্জিত টানার নমুনা বারাণসীতে পৌঁছেছে! জ্যামিতিক বিন্যাস অসাধারণ।",
    "Sharing the workshop address in Pochampally where our master weavers are preparing the warp frames.": "পোচমপল্লীতে কর্মশালার ঠিকানা শেয়ার করছি যেখানে আমাদের তাঁতিরা টানার ফ্রেম প্রস্তুত করছেন।",
    "Pochampally Ikat Weavers Colony": "পোচমপল্লী ইকত তাঁতি কলোনি",
    "Here is our Kadwa Floral Zari border pattern draft for our festive stole collection.": "আমাদের উৎসব স্টোল সংগ্রহের জন্য কাদওয়া ফ্লোরাল জরি পাড়ের প্যাটার্ন ড্রাফট এখানে দেওয়া হলো।",
    "Dr. Khatri ji, I dispatched two meters of handspun Katan silk for the pilot Ajrakh block printing test.": "ডাঃ খত্রী জী, আমি প্রাথমিক আজরখ ব্লক প্রিন্টিং পরীক্ষার জন্য দুই মিটার হাতে কাটা কাতান রেশম পাঠিয়েছি।",
    "Namaste Rajeshwar ji, I received your silk swatches. I will prepare the pomegranate mordant vat tomorrow.": "নমস্তে রাজেশ্বর জী, আমি আপনার রেশমের নমুনা পেয়েছি। আমি আগামীকাল ডালিম মর্দান্ট কুণ্ড প্রস্তুত করব।",
