    "Telangana is known for its vibrant handlooms, intricate crafts and rich cultural heritage. From the iconic Pochampally Ikat to exquisite metalwork, the state preserves centuries-old traditions through its artisans.": "તેલંગાણા તેના વાઇબ્રન્ટ હાથશાળ, જટિલ હસ્તકલા અને સમૃદ્ધ સાંસ્કૃતિક વારસા માટે જાણીતું છે. પ્રતિષ્ઠિત પોચમપલ્લી ઇકતથી લઈને ઉત્કૃષ્ટ ધાતુકળા સુધી, આ રાજ્ય તેના કારીગરો દ્વારા સદીઓ જૂની પરંપરાઓને જાળવી રાખે છે.",
