    "Mathematical double ikat tie-and-dye handwoven on manual tension pit-looms in Bhoodan Pochampally village. Both warp and weft yarns are pre-calculated, bundled, and dipped in living botanical indigofera and alizarin madder vats to create razor-sharp geometric chevron and diamond motifs. Certified GI craft of Telangana.": "ભૂદાન પોચમપલ્લી ગામમાં પરંપરાગત ખાડા શાળ (પિટ લૂમ) પર હાથથી વણેલી ગાણિતિક ચોકસાઈવાળી ડબલ ઇકત ટાઈ-એન્ડ-ડાઈ સાડી. તાણા અને વાણા બંને દોરાઓની અગાઉથી ગણતરી કરવામાં આવે છે, બાંધવામાં આવે છે અને કુદરતી ગળી અને મજીઠના રંગમાં બોળીને તીક્ષ્ણ ભૌમિતિક ભાત બનાવવામાં આવે છે. તેલંગાણાની પ્રમાણિત જીઆઈ હસ્તકલા.",
