    "The weight of the electroplated silver Zari on pure mulberry Katan silk is magnificent. Examining the reverse side confirms authentic Kadwa tapestry weaving with zero loose floating threads. The Digital Craft Passport and QR seal match the official UP GI register perfectly.": "શુદ્ધ શેતૂર કતાન સિલ્ક પર ઇલેક્ટ્રોપ્લેટેડ ચાંદીની જરીનું વજન અને અનુભૂતિ ભવ્ય છે. ઊંધી બાજુ તપાસતાં છૂટા દોરા વગરનું અસલ કડવા વણાટ સાબિત થાય છે. ડિજિટલ ક્રાફ્ટ પાસપોર્ટ અને ક્યૂઆર સીલ સત્તાવાર યુપી જીઆઈ રજિસ્ટર સાથે સંપૂર્ણ મેળ ખાય છે.",
