    "Jammu & Kashmir": "જમ્મુ અને કાશ્મીર",
    "5th-generation master pit-loom weaver from Madanpura, Varanasi. Recipient of National Master Craftsperson Award for revival of antique Kadwa floral brocades.": "મદનપુરા, વારાણસીના 5મી પેઢીના માસ્ટર વણકર. પ્રાચીન કડવા ફ્લોરલ બ્રોકેડના પુનરુત્થાન માટે રાષ્ટ્રીય એવોર્ડ વિજેતા.",
    "Master Ikat tie-and-dye mathematician and master weaver from Bhoodan Pochampally. Renowned for complex double ikat chevrons and training over 80 rural women weavers.": "ભૂદાન પોચમપલ્લીના માસ્ટર ઇકત વણકર. જટિલ ડબલ ઇકત ભાત અને 80 થી વધુ ગ્રામીણ મહિલા વણકરોને તાલીમ આપવા માટે જાણીતા.",
    "State Awardee artist preserving the traditional Kohbar and Kachni line styles. Her paintings bring ancient ecological folklore to contemporary handmade bamboo-cotton surfaces.": "પરંપરાગત કોહબર અને કચની શૈલીનું જતન કરતાં રાજ્ય પુરસ્કાર વિજેતા કલાકાર. વાંસ-કપાસની સપાટી પર પ્રાચીન લોકકથાઓને જીવંત કરે છે.",
    "Renowned 9th-generation natural dye master and Ajrakh block printer. Globally celebrated for reviving zero-chemical indigo and pomegranate natural mordants.": "પ્રખ્યાત 9મી પેઢીના કુદરતી રંગ નિષ્ણાત અને અજરખ બ્લોક પ્રિન્ટર. કેમિકલ મુક્ત કુદરતી ગળીના પુનર્જીવન માટે વૈશ્વિક સ્તરે જાણીતા.",
    "Direct disciple of master Kripal Singh Shekhawat. Dedicated to preserving single-fire cobalt oxide ceramics and training next-generation studio potters.": "માસ્ટર કૃપાલ સિંહ શેખાવતના સીધા શિષ્ય. કોબાલ્ટ ઓક્સાઇડ સિરામિક્સનું જતન કરવા અને નવી પેઢીને તાલીમ આપવા માટે સમર્પિત.",
    "Tribal Master Metallurgist carrying forward 4,500-year-old Cire Perdue lost-wax casting. Recognized for majestic tribal processional elephants and folk deities.": "4,500 વર્ષ જૂની ખોવાયેલી મીણ ઢાળવાની કળાને આગળ ધપાવતાં આદિવાસી માસ્ટર ધાતુશિલ્પી. ભવ્ય હાથીઓ અને લોકદેવી-દેવતાઓ માટે જાણીતા.",
    "Master of the Kani loom and coded Talim scripts. Preserving authentic 100% Changthangi hand-spun pashmina without synthetic blending.": "કાની સાળ અને તાલીમ લિપિના ઉસ્તાદ. કોઈ પણ કૃત્રિમ મિશ્રણ વિના 100% અસલ ચાંગથાંગી હાથકતાઈ પશ્મિનાનું જતન કરે છે.",
    "Kadwa Weaving": "કડવા વણાટ",
