    "Custom Project": "કસ્ટમ પ્રોજેક્ટ",
    "Kadwa Brocade Silk & Cast Brass Evening Clutches": "કડવા બ્રોકેડ સિલ્ક અને પિત્તળ ઇવનિંગ ક્લચ",
    "Pair hand-cast 4,500-year-old Cire Perdue brass tribal motifs as clasp hardware and decorative handles with antique pure silver Zari Kadwa woven silk.": "પ્રાચીન શુદ્ધ ચાંદીની જરી કડવા રેશમ સાથે પિત્તળ આદિવાસી કલાકૃતિઓ જોડો.",
    "High luxury festive bridal & international collector appeal.": "અતિ વૈભવી તહેવારી કન્યા અને આંતરરાષ્ટ્રીય સંગ્રહકોનું આકર્ષણ.",
    "Royal Kadwa Silk & Geometric Double Ikat Capsule Stoles": "રોયલ કડવા સિલ્ક અને ભૌમિતિક ડબલ ઇકત સ્ટોલ",
    "Integrate precision double ikat chevron bands seamlessly into the drape pallu with Kadwa brocade floral borders on mulberry silk warp.": "શેતૂર રેશમના તાણા પર કડવા ફૂલોની કિનારી સાથે પાલવમાં ડબલ ઇકત ભાત જોડો.",
    "Substantial demand among conscious handloom connoisseurs.": "જાગૃત હાથશાળ પારખુઓમાં નોંધપાત્ર માંગ.",
    "Natural Indigo Ajrakh Resist Printing on Handspun Katan Brocade": "હાથકતાઈ કાતાન બ્રોકેડ પર કુદરતી ગળી અજરખ રેઝિસ્ટ છાપકામ",
    "16-step natural indigo and pomegranate rind resist block printing on unbleached pure Katan silk grounds, bordered by handwoven gold zari.": "હાથવણાટ સોનાની જરીની કિનારીવાળા શુદ્ધ કાતાન રેશમ પર 16-તબક્કાનું કુદરતી ગળી બ્લોક છાપકામ.",
    "Premium export demand across European ethical fashion houses.": "યુરોપિયન ફેશન ગૃહોમાં પ્રીમિયમ નિકાસ માંગ.",
    "Jaipur Quartz Ceramic Knobs Mounted on Zari Silk Chests": "જરી સિલ્ક પેટીઓ પર જડેલા જયપુર ક્વાર્ટ્ઝ સિરામિક નોબ્સ",
    "Bespoke hand-painted cobalt and copper oxide floral ceramic medallions mounted as heirloom hardware on handwoven textile decor pieces.": "હાથવણાટ કાપડની સજાવટ પર હેરીટેજ હાર્ડવેર તરીકે જડેલા સિરામિક મેડલિયન્સ.",
    "High-end architectural boutique hotels & interior designers.": "ઉચ્ચ સ્તરીય બુટિક હોટેલ્સ અને ઇન્ટિરિયર ડિઝાઇનર્સ.",
    "Luxury Wear": "લક્ઝરી વસ્ત્રો",
    "Zero Plastic": "શૂન્ય પ્લાસ્ટિક",
