    "Mathematical double ikat tie-and-dye handwoven on manual tension pit-looms in Bhoodan Pochampally village. Both warp and weft yarns are pre-calculated, bundled, and dipped in living botanical indigofera and alizarin madder vats to create razor-sharp geometric chevron and diamond motifs. Certified GI craft of Telangana.": "ਭੂਦਾਨ ਪੋਚਮਪੱਲੀ ਪਿੰਡ ਵਿੱਚ ਰਵਾਇਤੀ ਖੱਡੀ 'ਤੇ ਹੱਥ ਨਾਲ ਬੁਣੀ ਗਈ ਗਣਿਤਕ ਸ਼ੁੱਧਤਾ ਵਾਲੀ ਡਬਲ ਇਕਤ ਟਾਈ-ਐਂਡ-ਡਾਈ ਸਾੜ੍ਹੀ। ਤਾਣਾ ਅਤੇ ਪੇਟਾ ਦੋਵਾਂ ਧਾਗਿਆਂ ਦੀ ਪਹਿਲਾਂ ਗਣਨਾ ਕੀਤੀ ਜਾਂਦੀ ਹੈ, ਬੰਨ੍ਹਿਆ ਜਾਂਦਾ ਹੈ ਅਤੇ ਕੁਦਰਤੀ ਨੀਲ ਤੇ ਮਜੀਠ ਦੇ ਰੰਗ ਵਿੱਚ ਡੁਬੋ ਕੇ ਤਿੱਖੇ ਜਿਓਮੈਟ੍ਰਿਕ ਨਮੂਨੇ ਬਣਾਏ ਜਾਂਦੇ ਹਨ। ਤੇਲੰਗਾਨਾ ਦੀ ਪ੍ਰਮਾਣਿਤ ਜੀਆਈ ਦਸਤਕਾਰੀ।",
