    "The weight of the electroplated silver Zari on pure mulberry Katan silk is magnificent. Examining the reverse side confirms authentic Kadwa tapestry weaving with zero loose floating threads. The Digital Craft Passport and QR seal match the official UP GI register perfectly.": "ਸ਼ੁੱਧ ਸ਼ਹਿਤੂਤ ਕਤਾਨ ਰੇਸ਼ਮ 'ਤੇ ਇਲੈਕਟ੍ਰੋਪਲੇਟਿਡ ਚਾਂਦੀ ਦੀ ਜ਼ਰੀ ਦਾ ਭਾਰ ਅਤੇ ਦਿੱਖ ਸ਼ਾਨਦਾਰ ਹੈ। ਉਲਟੇ ਪਾਸੇ ਦੀ ਜਾਂਚ ਕਰਨ 'ਤੇ ਬਿਨਾਂ ਢਿੱਲੇ ਧਾਗਿਆਂ ਦੇ ਅਸਲ ਕੜਵਾ ਬੁਣਾਈ ਦੀ ਪੁਸ਼ਟੀ ਹੁੰਦੀ ਹੈ। ਡਿਜੀਟਲ ਕਰਾਫਟ ਪਾਸਪੋਰਟ ਅਤੇ ਕਿਊਆਰ ਸੀਲ ਅਧਿਕਾਰਤ ਯੂਪੀ ਜੀਆਈ ਰਜਿਸਟਰ ਨਾਲ ਬਿਲਕੁਲ ਮੇਲ ਖਾਂਦੇ ਹਨ।",
