    "Arjun Nambiar": "ਅਰਜੁਨ ਨਾਂਬੀਆਰ",
    "Bengaluru, Karnataka": "ਬੰਗਲੌਰ, ਕਰਨਾਟਕ",
    "Shipped directly from the master weaver’s loom in Varanasi within 4 business days. Knowing that 82% of the price went directly to the artisan family without boutique commissions makes this purchase deeply fulfilling.": "ਵਾਰਾਣਸੀ ਵਿੱਚ ਮਾਸਟਰ ਜੁਲਾਹੇ ਦੀ ਖੱਡੀ ਤੋਂ ਸਿੱਧਾ 4 ਕੰਮਕਾਜੀ ਦਿਨਾਂ ਵਿੱਚ ਭੇਜਿਆ ਗਿਆ। ਬੁਟੀਕ ਕਮਿਸ਼ਨ ਤੋਂ ਬਿਨਾਂ ਕੀਮਤ ਦਾ 82% ਸਿੱਧਾ ਕਾਰੀਗਰ ਪਰਿਵਾਰ ਨੂੰ ਜਾਣ ਦੀ ਜਾਣਕਾਰੀ ਇਸ ਖਰੀਦ ਨੂੰ ਬਹੁਤ ਸੰਤੁਸ਼ਟੀਜਨਕ ਬਣਾਉਂਦੀ ਹੈ।",
