    "5th-generation master pit-loom weaver from Madanpura, Varanasi. Recipient of National Master Craftsperson Award for revival of antique Kadwa floral brocades.": "ਮਦਨਪੁਰਾ, ਵਾਰਾਣਸੀ ਦੇ 5ਵੀਂ ਪੀੜ੍ਹੀ ਦੇ ਮਾਸਟਰ ਬੁਣਕਰ। ਪੁਰਾਤਨ ਕੜਵਾ ਬਰੋਕੇਡ ਨੂੰ ਮੁੜ ਸੁਰਜੀਤ ਕਰਨ ਲਈ ਰਾਸ਼ਟਰੀ ਪੁਰਸਕਾਰ ਜੇਤੂ।",
    "Master Ikat tie-and-dye mathematician and master weaver from Bhoodan Pochampally. Renowned for complex double ikat chevrons and training over 80 rural women weavers.": "ਭੂਦਾਨ ਪੋਚਮਪੱਲੀ ਦੀ ਮਾਸਟਰ ਇਕਤ ਬੁਣਕਰ। ਗੁੰਝਲਦਾਰ ਡਬਲ ਇਕਤ ਡਿਜ਼ਾਈਨ ਅਤੇ 80 ਤੋਂ ਵੱਧ ਪੇਂਡੂ ਔਰਤਾਂ ਨੂੰ ਸਿਖਲਾਈ ਦੇਣ ਲਈ ਮਸ਼ਹੂਰ।",
    "State Awardee artist preserving the traditional Kohbar and Kachni line styles. Her paintings bring ancient ecological folklore to contemporary handmade bamboo-cotton surfaces.": "ਰਵਾਇਤੀ ਕੋਹਬਰ ਅਤੇ ਕਚਨੀ ਸ਼ੈਲੀਆਂ ਨੂੰ ਸੰਭਾਲਣ ਵਾਲੀ ਰਾਜ ਪੁਰਸਕਾਰ ਜੇਤੂ ਕਲਾਕਾਰ। ਬਾਂਸ-ਕਪਾਹ ਦੀ ਸਤ੍ਹਾ 'ਤੇ ਲੋਕ ਕਹਾਣੀਆਂ ਨੂੰ ਜੀਵੰਤ ਕਰਦੀ ਹੈ।",
    "Renowned 9th-generation natural dye master and Ajrakh block printer. Globally celebrated for reviving zero-chemical indigo and pomegranate natural mordants.": "ਮਸ਼ਹੂਰ 9ਵੀਂ ਪੀੜ੍ਹੀ ਦੇ ਕੁਦਰਤੀ ਰੰਗ ਮਾਸਟਰ ਅਤੇ ਅਜਰਖ ਬਲਾਕ ਪ੍ਰਿੰਟਰ। ਕੈਮੀਕਲ ਰਹਿਤ ਨੀਲ ਨੂੰ ਮੁੜ ਸੁਰਜੀਤ ਕਰਨ ਲਈ ਵਿਸ਼ਵ ਪੱਧਰ 'ਤੇ ਪ੍ਰਸਿੱਧ।",
    "Direct disciple of master Kripal Singh Shekhawat. Dedicated to preserving single-fire cobalt oxide ceramics and training next-generation studio potters.": "ਮਾਸਟਰ ਕ੍ਰਿਪਾਲ ਸਿੰਘ ਸ਼ੇਖਾਵਤ ਦੇ ਸਿੱਧੇ ਸ਼ਾਗਿਰਦ। ਕੋਬਾਲਟ ਆਕਸਾਈਡ ਮਿੱਟੀ ਦੇ ਬਰਤਨ ਕਲਾ ਨੂੰ ਸੰਭਾਲਣ ਅਤੇ ਨਵੀਂ ਪੀੜ੍ਹੀ ਨੂੰ ਸਿਖਲਾਈ ਦੇਣ ਲਈ ਸਮਰਪਿਤ।",
    "Tribal Master Metallurgist carrying forward 4,500-year-old Cire Perdue lost-wax casting. Recognized for majestic tribal processional elephants and folk deities.": "4,500 ਸਾਲ ਪੁਰਾਣੀ ਮੋਮ-ਢਲਾਈ ਕਲਾ ਨੂੰ ਅੱਗੇ ਵਧਾਉਣ ਵਾਲੇ ਆਦਿਵਾਸੀ ਧਾਤੂ ਸ਼ਿਲਪੀ। ਸ਼ਾਨਦਾਰ ਹਾਥੀਆਂ ਅਤੇ ਲੋਕ ਦੇਵੀ-ਦੇਵਤਿਆਂ ਦੀਆਂ ਮੂਰਤੀਆਂ ਲਈ ਜਾਣੇ ਜਾਂਦੇ ਹਨ।",
    "Master of the Kani loom and coded Talim scripts. Preserving authentic 100% Changthangi hand-spun pashmina without synthetic blending.": "ਕਾਨੀ ਖੱਡੀ ਅਤੇ ਤਾਲੀਮ ਲਿਪੀ ਦੇ ਉਸਤਾਦ। ਬਿਨਾਂ ਮਿਲਾਵਟ ਦੇ ਅਸਲੀ 100% ਚਾਂਗਥਾਂਗੀ ਹੱਥ ਨਾਲ ਕੱਤੇ ਪਸ਼ਮੀਨਾ ਨੂੰ ਸੰਭਾਲ ਰਹੇ ਹਨ।",
