    "Pair hand-cast 4,500-year-old Cire Perdue brass tribal motifs as clasp hardware and decorative handles with antique pure silver Zari Kadwa woven silk.": "ਪੁਰਾਤਨ ਸ਼ੁੱਧ ਚਾਂਦੀ ਦੀ ਜ਼ਰੀ ਕੜਵਾ ਰੇਸ਼ਮ ਨਾਲ ਪਿੱਤਲ ਆਦਿਵਾਸੀ ਨਕਸ਼ਾਂ ਨੂੰ ਜੋੜੋ।",
    "High luxury festive bridal & international collector appeal.": "ਉੱਚ ਲਗਜ਼ਰੀ ਤਿਉਹਾਰੀ ਵਿਆਹ ਅਤੇ ਅੰਤਰਰਾਸ਼ਟਰੀ ਕੁਲੈਕਟਰ ਆਕਰਸ਼ਣ।",
    "Royal Kadwa Silk & Geometric Double Ikat Capsule Stoles": "ਰਾਇਲ ਕੜਵਾ ਸਿਲਕ ਅਤੇ ਜਿਓਮੈਟ੍ਰਿਕ ਡਬਲ ਇਕਤ ਸਟੋਲ",
    "Integrate precision double ikat chevron bands seamlessly into the drape pallu with Kadwa brocade floral borders on mulberry silk warp.": "ਸ਼ਹਿਤੂਤ ਰੇਸ਼ਮ ਦੇ ਤਾਣੇ 'ਤੇ ਕੜਵਾ ਫੁੱਲਾਂ ਦੇ ਬਾਰਡਰ ਨਾਲ ਪੱਲੂ ਵਿੱਚ ਡਬਲ ਇਕਤ ਪੱਟੀਆਂ ਸ਼ਾਮਲ ਕਰੋ।",
    "Substantial demand among conscious handloom connoisseurs.": "ਜਾਗਰੂਕ ਹੈਂਡਲੂਮ ਪ੍ਰੇਮੀਆਂ ਵਿੱਚ ਭਾਰੀ ਮੰਗ।",
    "Natural Indigo Ajrakh Resist Printing on Handspun Katan Brocade": "ਹੱਥ ਨਾਲ ਕੱਤੇ ਕਤਾਨ ਬਰੋਕੇਡ 'ਤੇ ਕੁਦਰਤੀ ਨੀਲ ਅਜਰਖ ਰੋਧਕ ਛਪਾਈ",
    "16-step natural indigo and pomegranate rind resist block printing on unbleached pure Katan silk grounds, bordered by handwoven gold zari.": "ਹੱਥ ਨਾਲ ਬੁਣੀ ਸੋਨੇ ਦੀ ਜ਼ਰੀ ਵਾਲੇ ਸ਼ੁੱਧ ਕਤਾਨ ਰੇਸ਼ਮ 'ਤੇ 16-ਪੜਾਵੀ ਕੁਦਰਤੀ ਨੀਲ ਬਲਾਕ ਛਪਾਈ।",
    "Premium export demand across European ethical fashion houses.": "ਯੂਰਪੀਅਨ ਫੈਸ਼ਨ ਹਾਊਸਾਂ ਵਿੱਚ ਪ੍ਰੀਮੀਅਮ ਨਿਰਯਾਤ ਮੰਗ।",
    "Jaipur Quartz Ceramic Knobs Mounted on Zari Silk Chests": "ਜ਼ਰੀ ਸਿਲਕ ਸੰਦੂਕਾਂ 'ਤੇ ਲੱਗੇ ਜੈਪੁਰ ਕੁਆਰਟਜ਼ ਸਿਰੇਮਿਕ ਨੌਬ",
    "Bespoke hand-painted cobalt and copper oxide floral ceramic medallions mounted as heirloom hardware on handwoven textile decor pieces.": "ਹੱਥ ਨਾਲ ਬੁਣੇ ਸਜਾਵਟੀ ਕੱਪੜਿਆਂ 'ਤੇ ਲਗਾਏ ਗਏ ਹੱਥ ਨਾਲ ਬਣਾਏ ਸਿਰੇਮਿਕ ਮੈਡਲਿਅਨ।",
