export const createTranslator = (lang: LanguageCode): TranslateFn => {
  const currentTranslations = translations[lang] || translations.en;
  const dict: Record<string, string> = {
    ...((currentTranslations as unknown as Record<string, string>) || {}),
    ...(SITE_DICTIONARY[lang] || {}),
    ...(EXTRA_DICTIONARY[lang] || {}),
    ...(ARTISAN_DICTIONARY[lang] || {}),
    ...(COMPREHENSIVE_UI_DICTIONARY[lang] || {}),
    ...(PAGE_AND_PRODUCT_TRANSLATIONS[lang] || {}),
  };

  const translateCallable = (text?: string): string => {
    if (!text || lang === 'en') return text || '';

    // 1. Direct match
    if (dict[text]) return dict[text];

    // 2. Trimmed match
    const trimmed = text.trim();
    if (dict[trimmed]) return dict[trimmed];

    // 3. Dynamic "Welcome, [Name]" pattern (exclude full descriptive titles like "Welcome to ...")
    if (
      (trimmed.startsWith('Welcome, ') || (trimmed.startsWith('Welcome ') && !trimmed.startsWith('Welcome to '))) &&
      !dict[trimmed]
    ) {
      const name = trimmed.replace(/^Welcome,?\s*/, '');
      const welcomeWord = dict['Welcome'] || 'Welcome';
      return `${welcomeWord}, ${name}`;
    }

    // 4. Dynamic trailing arrow e.g. "Review proposals →" or "View all orders →"
    if (trimmed.endsWith(' →') || trimmed.endsWith(' ->')) {
      const base = trimmed.replace(/\s*(→|->)$/, '').trim();
      if (dict[base]) return `${dict[base]} →`;
    }

    // 5. Dynamic trailing colon e.g. "Guild:" or "Customer:" or "Item:" or "Tracking:"
    if (trimmed.endsWith(':')) {
      const base = trimmed.slice(0, -1).trim();
      if (dict[base]) return `${dict[base]}:`;
    }

    // 6. Dynamic count in parentheses e.g. "Active Loom Fulfillment (1)" or "Orders (2)" or "Discover Artisans (5)"
    const countMatch = trimmed.match(/^(.*?)\s*\(([0-9]+)\)$/);
    if (countMatch) {
      const base = countMatch[1].trim();
      const count = countMatch[2];
      if (dict[base]) return `${dict[base]} (${count})`;
    }

    // 7. Dynamic count with space e.g. "Orders 1"
    const countSpaceMatch = trimmed.match(/^(.*?)\s+([0-9]+)$/);
    if (countSpaceMatch) {
      const base = countSpaceMatch[1].trim();
      const count = countSpaceMatch[2];
      if (dict[base]) return `${dict[base]} ${count}`;
    }

    // 8. Dynamic trailing ellipsis e.g. "Search state, craft or GI tag..."
    if (trimmed.endsWith('...')) {
      const base = trimmed.slice(0, -3).trim();
      if (dict[base]) return `${dict[base]}...`;
    }

    // 9. Case-insensitive fallback
    const lowerKey = Object.keys(dict).find((k) => k.toLowerCase() === trimmed.toLowerCase());
    if (lowerKey && dict[lowerKey]) return dict[lowerKey];

    return text;
  };

  return Object.assign(translateCallable, currentTranslations);
};

